+      g.strokeStyle=`rgba(${20+Math.random()*40|0},${12+Math.random()*22|0},6,${0.08+Math.random()*0.22})`;
+      g.lineWidth=0.6+Math.random()*1.6; g.beginPath(); g.moveTo(x,y);
