+    }
+    for(let k=0;k<2;k++){ // knots
+      const x=Math.random()*w, y=r*rh+rh*(0.25+Math.random()*0.5);
+      const gr=g.createRadialGradient(x,y,1,x,y,14+Math.random()*10);
+      gr.addColorStop(0,'rgba(25,12,4,.85)'); gr.addColorStop(1,'rgba(25,12,4,0)');
+      g.fillStyle=gr; g.beginPath(); g.arc(x,y,24,0,7); g.fill();
+    }
+    g.fillStyle='rgba(0,0,0,.55)'; g.fillRect(0,r*rh,w,2);
+  }
+}, 2, 1);
+const woodRough = canvasTex(512,256,(g,w,h)=>{
+  g.fillStyle='#8a8a8a'; g.fillRect(0,0,w,h);
+  for(let i=0;i<5000;i++){ g.fillStyle=`rgba(${90+Math.random()*90|0},0,0,0)`;
+    g.fillStyle=`rgba(${90+Math.random()*90|0},${90+Math.random()*90|0},${90+Math.random()*90|0},.25)`;
+    g.fillRect(Math.random()*w,Math.random()*h,8+Math.random()*30,1); }
+},2,1); woodRough.colorSpace = THREE.NoColorSpace;
+const brushedTex = canvasTex(512,512,(g,w,h)=>{
+  g.fillStyle='#7d7d7d'; g.fillRect(0,0,w,h);
