+moon.shadow.mapSize.set(1024,1024); moon.shadow.bias = -0.0004;
+moon.shadow.camera.left=-6; moon.shadow.camera.right=6; moon.shadow.camera.top=6; moon.shadow.camera.bottom=-6;
+scene.add(moon);
+
+const table = new THREE.Mesh(
+  new THREE.BoxGeometry(14, 0.22, 9),
+  new THREE.MeshStandardMaterial({ map:woodTex, roughnessMap:woodRough, roughness:0.75, metalness:0.02 }));
+table.position.y = -0.11; table.receiveShadow = true; scene.add(table);
+
+const floor = new THREE.Mesh(new THREE.PlaneGeometry(40,40),
+  new THREE.MeshStandardMaterial({ color:0x17120e, roughness:0.95 }));
+floor.rotation.x = -Math.PI/2; floor.position.y = -2.4; floor.receiveShadow = true; scene.add(floor);
+const legMat = new THREE.MeshStandardMaterial({ color:0x241a11, roughness:0.85 });
+for (const [x,z] of [[-5.6,-3.4],[5.6,-3.4],[-5.6,3.4],[5.6,3.4]]){
+  const leg = new THREE.Mesh(new THREE.BoxGeometry(0.3,2.3,0.3), legMat);
+  leg.position.set(x,-1.35,z); leg.castShadow=true; scene.add(leg);
+}
+const wallMat = new THREE.MeshStandardMaterial({ map:wallTex, roughness:0.96 });
+const backWall = new THREE.Mesh(new THREE.PlaneGeometry(30,14), wallMat);
+backWall.position.set(0,4.5,-4.6); backWall.receiveShadow=true; scene.add(backWall);
