+mug.position.set(1.75,0.15,-0.7); mug.castShadow=mug.receiveShadow=true; scene.add(mug);
+const mugBottom = new THREE.Mesh(new THREE.CircleGeometry(0.14,32), mug.material);
+mugBottom.rotation.x=-Math.PI/2; mugBottom.position.set(1.75,0.005,-0.7); scene.add(mugBottom);
