+handle.position.set(1.93,0.15,-0.7); handle.rotation.z=-Math.PI/2; handle.castShadow=true; scene.add(handle);
+const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.26,0.2,0.4,24),
