+  color:0x3a3632, metalness:0.85, roughness:0.45, roughnessMap:brushedTex, envMapIntensity:0.7 });
+
+function lathe(pts, mat, seg=72){
+  const m = new THREE.Mesh(new THREE.LatheGeometry(pts.map(p=>new THREE.Vector2(p[0],p[1])), seg), mat);
+  m.castShadow = true; m.receiveShadow = true; lamp.add(m); return m;
+}
+/* conical base hiding the bulb */
+lathe([[0.001,0],[0.62,0],[0.79,0.015],[0.805,0.07],[0.74,0.2],[0.63,0.5],[0.55,0.82],
