+  new THREE.MeshStandardMaterial({ color:0x100d0b, roughness:1 }));
+pad.position.y = 0.01; lamp.add(pad);
+
+/* glass vessel — real wall profile with rounded sealed top */
+const glassPts = [];
+glassPts.push([0.001, 0.905],[0.34,0.91],[0.55,0.94]);
+for(let i=0;i<=28;i++){ const y = IB + (IT-IB)*i/28; glassPts.push([vesselR(y)+0.062, y]); }
+glassPts.push([0.3,3.22],[0.22,3.3],[0.1,3.36],[0.001,3.38]);
+const glassMat = new THREE.MeshPhysicalMaterial({
+  color:0xffffff, metalness:0, roughness:0.035, transmission:1, thickness:0.09,
+  ior:1.5, clearcoat:0.6, clearcoatRoughness:0.08, envMapIntensity:1.2,
+  specularIntensity:1.1, side:THREE.DoubleSide });
+const glass = lathe(glassPts, glassMat); glass.castShadow=false; glass.renderOrder=30;
+
+/* tinted liquid volume just inside the glass */
+const liqPts = [[0.001,IB+0.005]];
+for(let i=0;i<=28;i++){ const y = IB + (IT-IB-0.06)*i/28; liqPts.push([Math.max(0.02,vesselR(y)-0.012), y]); }
+liqPts.push([0.001, IT-0.02]);
+const liquidMat = new THREE.MeshPhysicalMaterial({
