+bulb.scale.set(1, 1.45, 1); bulb.position.y = 1.1; lamp.add(bulb);
+const bulbBase = new THREE.Mesh(new THREE.CylinderGeometry(0.07,0.085,0.14,20), darkMetal);
+bulbBase.position.y = 0.95; lamp.add(bulbBase);
+
+const bulbLight = new THREE.PointLight(0xffa63d, 22, 14, 1.9);
+bulbLight.position.set(0, 1.45, 0); bulbLight.castShadow = true;
+bulbLight.shadow.mapSize.set(1024,1024); bulbLight.shadow.bias = -0.004;
+bulbLight.shadow.camera.near = 0.15; bulbLight.shadow.camera.far = 13;
