+const haloGlow = glowSprite(0xff8a30, 4.4, 0.13); haloGlow.position.y = 1.9; haloGlow.renderOrder=24; lamp.add(haloGlow);
+
+/* power cord trailing off the table + inline switch */
+const cordPts = [
+  new THREE.Vector3(0, 0.28, -0.72), new THREE.Vector3(-0.15, 0.1, -1.25),
+  new THREE.Vector3(-0.7, 0.045, -1.9), new THREE.Vector3(-1.55, 0.045, -2.25),
+  new THREE.Vector3(-2.6, 0.045, -2.5), new THREE.Vector3(-3.6, 0.04, -3.1),
