+  new THREE.MeshStandardMaterial({ color:0x17130f, roughness:0.65 }));
+cord.castShadow = cord.receiveShadow = true; scene.add(cord);
+const switchBox = new THREE.Group();
+const swBody = new THREE.Mesh(new THREE.BoxGeometry(0.3,0.09,0.16),
+  new THREE.MeshStandardMaterial({ color:0x211c17, roughness:0.5 }));
+swBody.castShadow = swBody.receiveShadow = true; switchBox.add(swBody);
