console.log("ROOM set to", await sliderTo("#room", 0.95));
await page.waitForTimeout(1200); await snap("lava-16-room-bright.png");
await sliderTo("#room", 0.34); await sliderTo("#heat", 0.39); await sliderTo("#waxAmt", 0.43);
// slow motion on/off
await clickCenter(page.locator(".tog label.switch").nth(0));
console.log("SLOWMO", JSON.stringify(await stateOf()));
await page.waitForTimeout(2500); await snap("lava-17-slowmo.png");
await clickCenter(page.locator(".tog label.switch").nth(0));
// auto-orbit on, observe camera move, off
