// manual orbit drag + zoom to close-up
await page.mouse.move(480, 360); await page.mouse.down();
await page.mouse.move(700, 300, { steps: 24 }); await page.mouse.up();
await page.waitForTimeout(600);
await page.mouse.move(550, 380); await page.mouse.wheel(0, -900);
await page.waitForTimeout(1500); await snap("lava-19-orbit-closeup.png");
await page.mouse.wheel(0, -600);
await page.waitForTimeout(1200); await snap("lava-20-closeup2.png");
console.log("ERRORS", JSON.stringify(errors));
console.log("FINAL", JSON.stringify({ fps, snapsCount: snaps.length, totalSec: elapsed() }));
await writeFile("lava-verify.json", JSON.stringify({ fps, errors, snaps }, null, 2));
