page.on("console", m => { if (m.type() === "error") errors.push(m.text()); });
await page.setViewportSize({ width: 1100, height: 760 });
const stateOf = () => page.evaluate(() => ({
  power: document.getElementById('power').checked,
  heat: document.getElementById('heat').value, wax: document.getElementById('waxAmt').value,
  room: document.getElementById('room').value, slowmo: document.getElementById('slowmo').checked,
  orbit: document.getElementById('autorot').checked,
  preset: [...document.querySelectorAll('.preset')].findIndex(e=>e.classList.contains('active'))
}));
async function snap(name){
  const p = await saveScreenshot(await page.screenshot(), name);
  console.log("SNAP", name, JSON.stringify(await stateOf()));
}
async function clickCenter(loc){
  const bb = await loc.boundingBox();
  await page.mouse.click(bb.x + bb.width/2, bb.y + bb.height/2);
}
await page.goto("file:///private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.TL4FBa/app/index.html");
await page.waitForTimeout(6000);
await snap("lit-01-flowing.png");
// 3D base switch OFF then ON at the same point
let pt = null;
outer: for (const cy of [672,666,678,660,650]) {
  for (const cx of [558,550,566,542,574,534,582]) {
    const before = (await stateOf()).power;
    await page.mouse.click(cx, cy); await page.waitForTimeout(100);
    if ((await stateOf()).power !== before) { pt = {x:cx,y:cy}; break outer; }
  }
}
console.log("3D OFF", JSON.stringify(pt), JSON.stringify(await stateOf()));
await page.waitForTimeout(2500); await snap("lit-02-3doff.png");
await page.mouse.click(pt.x, pt.y); await page.waitForTimeout(250);
console.log("3D ON same point", JSON.stringify(await stateOf()));
await page.waitForTimeout(7000); await snap("lit-03-3don-rewarmed.png");
// presets while lit
for (let i = 1; i <= 4; i++) {
  await page.locator(".preset").nth(i).click({ timeout: 5000 });
  await page.waitForTimeout(2200);
  await snap("lit-04-preset"+i+".png");
}
await page.locator(".preset").nth(0).click({ timeout: 5000 });
await page.waitForTimeout(2200); await snap("lit-05-classic-red-yellow.png");
// heat while lit
async function sliderTo(sel, frac){
  const bb = await page.locator(sel).boundingBox();
  await page.mouse.click(bb.x + bb.width*frac, bb.y + bb.height/2);
  await page.waitForTimeout(250);
  return page.evaluate(s => document.querySelector(s).value, sel);
}
console.log("HEAT ->", await sliderTo("#heat", 0.98));
await page.waitForTimeout(6000); await snap("lit-06-heat-max.png");
console.log("HEAT ->", await sliderTo("#heat", 0.02));
await page.waitForTimeout(5000); await snap("lit-07-heat-min.png");
await sliderTo("#heat", 0.39);
// wax amount while lit
console.log("WAX ->", await sliderTo("#waxAmt", 0.98));
await page.waitForTimeout(4500); await snap("lit-08-wax-max.png");
console.log("WAX ->", await sliderTo("#waxAmt", 0.02));
await page.waitForTimeout(3500); await snap("lit-09-wax-min.png");
await sliderTo("#waxAmt", 0.43);
// slow-mo while lit: two frames 3s apart, then normal speed two frames 3s apart
await clickCenter(page.locator(".tog label.switch").nth(0));
console.log("SLOWMO ON", JSON.stringify(await stateOf()));
await snap("lit-10-slowmo-a.png");
await page.waitForTimeout(3000); await snap("lit-11-slowmo-b.png");
await clickCenter(page.locator(".tog label.switch").nth(0));
console.log("SLOWMO OFF", JSON.stringify(await stateOf()));
await snap("lit-12-normal-a.png");
await page.waitForTimeout(3000); await snap("lit-13-normal-b.png");
// lit close-up after orbit+zoom
await page.mouse.move(480, 360); await page.mouse.down();
await page.mouse.move(690, 310, { steps: 20 }); await page.mouse.up();
await page.mouse.move(550, 380); await page.mouse.wheel(0, -1100);
await page.waitForTimeout(1800); await snap("lit-14-closeup-lit.png");
console.log("ERRORS", JSON.stringify(errors));
await browser.closePage("lava-lit");
